"""One SQL source of truth; generates the Metro-compatible string module."""
from pathlib import Path
import json
root = Path(__file__).resolve().parents[1]
sql = (root / 'specs/schema.sql').read_text()
(root / 'apps/mobile/src/data/schema.generated.ts').write_text(
    '// Generated by scripts/build_schema.py. Do not edit.\nexport const schema = ' + json.dumps(sql, ensure_ascii=False) + ';\n'
)
